create extension if not exists pgcrypto;
create table if not exists countries(id text primary key,name text not null,code text,population bigint,military_rank integer,economy_rank integer,raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists regions(id text primary key,name text not null,country_id text references countries(id),owner_country_id text references countries(id),is_core boolean not null default false,resistance numeric,raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists wars(id text primary key,attacker_country_id text references countries(id),defender_country_id text references countries(id),status text,raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists battles(id text primary key,war_id text references wars(id),region_id text references regions(id),attacker_country_id text references countries(id),defender_country_id text references countries(id),status text,attacker_damage numeric,defender_damage numeric,ends_at timestamptz,raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists military_units(id text primary key,name text not null,country_id text references countries(id),members_count integer,ranking integer,raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists player_profiles(id text primary key,username text,country_id text references countries(id),party_name text,military_unit_id text references military_units(id),raw jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists market_prices(id uuid primary key default gen_random_uuid(),item_id text not null,item_name text not null,country_id text references countries(id),price numeric not null,currency text,captured_at timestamptz not null default now());
create table if not exists resistance_snapshots(id uuid primary key default gen_random_uuid(),region_id text not null references regions(id) on delete cascade,resistance numeric not null,owner_country_id text references countries(id),captured_at timestamptz not null default now());
create table if not exists battle_snapshots(id uuid primary key default gen_random_uuid(),battle_id text not null references battles(id) on delete cascade,attacker_damage numeric,defender_damage numeric,captured_at timestamptz not null default now());
create table if not exists intelligence_events(id uuid primary key default gen_random_uuid(),event_type text not null,severity text not null default 'info',country_id text references countries(id),region_id text references regions(id),entity_id text,title text not null,summary text,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists server_configs(guild_id text primary key,primary_country_id text references countries(id),alert_channel_id text,command_channel_id text,settings jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists alert_subscriptions(id uuid primary key default gen_random_uuid(),guild_id text not null,channel_id text not null,event_type text not null,country_id text references countries(id),region_id text references regions(id),threshold numeric,enabled boolean not null default true,created_at timestamptz not null default now());
create table if not exists watchlists(id uuid primary key default gen_random_uuid(),guild_id text not null,entity_type text not null,entity_id text not null,label text,created_at timestamptz not null default now(),unique(guild_id,entity_type,entity_id));
create table if not exists sync_state(provider text not null,resource text not null,last_success_at timestamptz,last_error text,cursor text,updated_at timestamptz not null default now(),primary key(provider,resource));
create index if not exists idx_regions_country on regions(country_id);
create index if not exists idx_resistance_region_time on resistance_snapshots(region_id,captured_at desc);
create index if not exists idx_events_time on intelligence_events(occurred_at desc);
